INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1320524-ise443', 'stk-user2352', 'ISE 443', 'info', '{"desc": "هندسة العوامل البشرية\nمبادئ تشريح ووظائف أعضاء الجسم البشري، جمع وعرض معلومات بيانات المقدرة والكفاءة البشرية، تخطيط مكان العمل (أبعاد واحتياجات مكان العمل، مكان العامل ولوحات المعلومات، مبادئ التخطيط)، نظم العامل والآلة (علاقة الإنسان بالآلة، مكان العمل وبيئة العمل، ملاحظة وإدراك العامل للمعلومات والاستجابة لها، قدرات العامل والآلة، السمات الاجتماعية للعمل).\n( هندسة العوامل البشرية )\nمقدمة للعوامل الإنسانية لدارسة أنظمة العلاقة بين العامل والمعدة وظروف العمل ؛ نظرية المعلومات ؛ القدرات الإنسانية وعوامل وظائف الأعضاء ؛ العوامل البيئية والحرارية المؤثرة ؛ تصميم أماكن العمل والأدوات اليدوية والأجهزة والتحكم و المراقبة ؛ مهارات التواصل بين العامل والمعدة والمناولة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-443-human-factors-engineering/152559/4", "user": "user2352", "ts": 1390028246000, "tid": 152559, "pn": 4}}', 1390028246000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p843795-ise443', 'stk-fond_of_you', 'ISE 443', 'info', '{"desc": "شوف اي مادة مع حبوبي اكيد تصير سهلة لكن انتبه من التصحيح والقريد ماكو …\nانا لما رحت ليوم المهنة الترم اللي فات سالت خمس شركات …\nيونليفير و بيكر هيوزر و نستله و قودي و P&G …\nنصحوني بالمواد التالية طبعا ما كل الشركات اتفقوا لكن الاغلب :\n\nsupply chain & industrial baalance score card all companies\nre-engineering + quality control 2 some of them\n\nموفق وانصحك تمهل شوي 😉", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise443/107516/2", "user": "Fond_Of_You", "ts": 1305262253000, "tid": 107516, "pn": 2}}', 1305262253000, 1794826864, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
